class Solution {
    public: vector<int> maxProductPair(vector<int>& a,int target) {
        long long best=LLONG_MIN;
        vector<int> ans= {
            -1,-1
        }
        ;
        for(int i=0; i<(int)a.size(); i++)for(int j=0; j<(int)a.size(); j++)if(i!=j&&a[i]>a[j]&&a[i]+a[j]==target) {
            long long p=1LL*a[i]*a[j];
            if(p>best) {
                best=p;
                ans= {
                    i,j
                }
                ;
            }
        }
        return ans;
    }
}
